from pwn import *
import itertools

# Load helper functions from almostxor.py
def to_num(s):
    x = 0
    for i in range(len(s)):
        x += ord(s[-1 - i]) * pow(256, i)
    return x

def get_nums(s, n):
    sections = [s[i:i + n] for i in range(0, len(s), n)]
    sections[-1] = sections[-1] + ("\x00" * (n - len(sections[-1])))
    return [to_num(x) for x in sections]

def get_vals(x, n):
    vals = []
    mask = (1 << n) - 1
    for i in range(8):
        vals.append(x & mask)
        x = x >> n
    vals.reverse()
    return vals

def get_chrs(val_list, n):
    x = val_list[0]
    chrs = []
    for i in range(1, len(val_list)):
        x <<= n
        x += val_list[i]
    for i in range(n):
        chrs.append(chr(x % 256))
        x //= 256
    chrs.reverse()
    return "".join(chrs)

def decr_vals(c_chr, k_chr, n):
    return (c_chr - k_chr) & ((1 << n) - 1)

def decrypt(k, c, n):
    rep_k = k * (len(c) // len(k)) + k[:len(c) % len(k)]
    c_val_list = [get_vals(x, n) for x in get_nums(c, n)]
    k_val_list = [get_vals(x, n) for x in get_nums(rep_k, n)]
    c_vals, k_vals, m_vals = [], [], []
    for lst in c_val_list:
        c_vals += lst
    for lst in k_val_list:
        k_vals += lst
    m_vals = [decr_vals(c_vals[i], k_vals[i % len(k_vals)], n) for i in range(0, len(c_vals))]
    m_val_list = [m_vals[i:i + 8] for i in range(0, len(m_vals), 8)]
    return "".join([get_chrs(lst, n) for lst in m_val_list])

# Constants
ciphertext_path = "/home/ctfplayer/ctf_files/ciphertext"
ASCII_ALPHANUMERIC = "0123456789ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz"

# Load ciphertext
with open(ciphertext_path, "rb") as f:
    ciphertext = f.read()

# Attempt decryption for n=6 and n=7
possible_ns = [6, 7]
for n in possible_ns:
    print(f"Trying n={n}")

    # Iterate through possible keys (alphanumeric keys, length <= 8 for efficiency)
    for key_len in range(1, 9):
        for key_tuple in itertools.product(ASCII_ALPHANUMERIC, repeat=key_len):
            key = "".join(key_tuple)
            try:
                plaintext = decrypt(key, ciphertext, n)
                if "flag{" in plaintext:
                    print(f"[+] Flag found with n={n}, key={key}: {plaintext}")
                    exit(0)
            except Exception as e:
                continue

print("[-] Flag not found. Try expanding the keyspace or refining parameters.")

