from almostxor import get_nums, get_vals
import itertools

def decrypt(ciphertext, n):
    ciphertext = ciphertext.decode('latin1')
    ciphertext_nums = get_nums(ciphertext, n)
    val_lists = [get_vals(c, n) for c in ciphertext_nums]
    flat_cipher_vals = [val for sublist in val_lists for val in sublist]

    printable_ascii = range(32, 127)
    probable_keyspace = itertools.product(printable_ascii, repeat=n)

    for key in probable_keyspace:
        key_vals = list(key)
        decrypted_vals = []

        for i, c_val in enumerate(flat_cipher_vals):
            k_val = key_vals[i % n]
            decrypted_vals.append((c_val - k_val) & ((1 << n) - 1))

        decrypted_chars = ''.join([chr(v) if 32 <= v <= 126 else '.' for v in decrypted_vals])
        if 'flag{' in decrypted_chars:
            return ''.join(decrypted_chars)

    return None

if __name__ == "__main__":
    with open("/home/ctfplayer/ctf_files/ciphertext", "rb") as f:
        ciphertext = f.read().strip()

    for n in [6, 7]:
        result = decrypt(ciphertext, n)
        if result:
            print(f"Decryption successful for n={n}: {result}")
            break
    else:
        print("Decryption failed.")

